import BookingFlow from "../../../booking/BookingFlow";
import { fetchCheckRate, toBookingSummary, type BookingSummary } from "@/lib/booking";
import { buildBookingMeta } from "@/lib/booking-meta";
import type { BookingMeta } from "@/lib/booking-form";
import { getHotelDetails } from "@/lib/hotels-api";
import { parseSearchParams } from "@/lib/hotels";

export const dynamic = "force-dynamic";

export default async function BookPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { id } = await params;
  const sp = await searchParams;
  const search = parseSearchParams(sp);

  const rawKey = sp.rateKey;
  const rateKey = (Array.isArray(rawKey) ? rawKey[0] : rawKey) ?? "";

  // back to the hotel page with the same search
  const hotelHref = `/hotels/${id}?${new URLSearchParams({
    checkIn: search.checkIn,
    checkOut: search.checkOut,
    adults: String(search.adults),
    children: String(search.children),
    rooms: String(search.rooms),
  })}`;

  let summary: BookingSummary | null = null;
  let meta: BookingMeta | null = null;
  let error: string | null = null;

  if (!rateKey || !search.checkIn || !search.checkOut) {
    error = "This booking link is incomplete. Please choose a room again.";
  } else {
    try {
      const raw = await fetchCheckRate(rateKey);
      summary = raw ? toBookingSummary(raw, search) : null;

      if (!summary) {
        error = "This room is no longer available at that price. Please choose another room.";
      } else if (raw) {
        // hotel details (address, phone, images...) are not in the checkrate response
        const details = await getHotelDetails([Number(id)]).catch(() => null);
        meta = buildBookingMeta({
          raw,
          details,
          checkIn: search.checkIn,
          checkOut: search.checkOut,
        });
      }
    } catch {
      error = "We couldn't confirm this room right now. Please try again.";
    }
  }

  return (
    <BookingFlow
      summary={summary}
      meta={meta as BookingMeta}
      error={error}
      hotelHref={hotelHref}
      adults={search.adults}
      children={search.children}
      rooms={search.rooms}
    />
  );
}