// lib/booking-meta.ts
import type { RawCheckRateHotel } from "@/lib/booking";
import type { BookingMeta } from "@/lib/booking-form";

/** Trims a string and cuts it to the hotels_bookings schema maxlength so Mongoose never rejects the save. */
const cut = (v: unknown, max: number): string => (typeof v === "string" ? v.trim().slice(0, max) : "");

/** "4 STARS" -> "4". The schema allows only 5 characters for `stars`. */
const starsOf = (v: unknown): string => {
  const m = /(\d)/.exec(typeof v === "string" ? v : "");
  return m ? m[1] : "";
};

export function buildBookingMeta(a: {
  raw: RawCheckRateHotel;
  details: Record<string, any> | null;
  checkIn: string; // YYYY-MM-DD
  checkOut: string; // YYYY-MM-DD
}): BookingMeta {
  const d = a.details ?? {};
  const room = a.raw.rooms?.[0];
  const rate = room?.rates?.[0];

  const price = Number(rate?.sellingRate ?? rate?.net ?? 0);

  // pay-at-hotel taxes only, same rule as toBookingSummary
  const taxes = (rate?.taxes?.taxes ?? [])
    .filter((t) => t.included === false)
    .reduce((sum, t) => sum + Number(t.clientAmount ?? t.amount ?? 0), 0);

  const img = d.images?.[0]?.path ? `https://photos.hotelbeds.com/giata/bigger/${d.images[0].path}` : "";
  const lat = d.coordinates?.latitude;
  const lng = d.coordinates?.longitude;

  return {
    hotel: {
      id: a.raw.code,
      name: cut(a.raw.name ?? d.name, 100),
      stars: starsOf(d.categoryName ?? d.category?.description?.content),
      phone: d.phones?.[0]?.phoneNumber ?? "",
      email: cut(d.email, 50),
      website: cut(d.web ?? d.website, 50),
      address: cut(d.address?.content ?? d.address, 500),
      img,
      location: cut(d.zone?.name ?? d.zoneName, 250),
      locationCords: lat != null && lng != null ? cut(`${lat},${lng}`, 250) : "",
    },
    checkIn: a.checkIn,
    checkOut: a.checkOut,
    price,
    currency: a.raw.currency ?? "EUR",
    taxes,
    roomName: cut(room?.name ?? room?.code, 500),
    board: cut(rate?.boardName ?? rate?.boardCode ?? "Room only", 500),
    supplier: "Hotelbeds",
  };
}