// lib/booking.ts
import { countNights, formatDate } from "@/lib/hotels";

/* ---------------- raw checkrates shapes (standard Hotelbeds) ------------- */

type RawRate = {
  rateKey: string;
  rateType?: string; // BOOKABLE | RECHECK
  net?: string;
  sellingRate?: string;
  paymentType?: string; // AT_WEB | AT_HOTEL
  boardCode?: string;
  boardName?: string;
  rateComments?: string;
  cancellationPolicies?: { amount?: string; from: string }[];
  taxes?: {
    taxes?: {
      included?: boolean;
      amount?: string;
      currency?: string;
      clientAmount?: string;
      clientCurrency?: string;
    }[];
  };
};

export type RawCheckRateHotel = {
  code: number;
  name?: string;
  currency?: string;
  rooms?: { code: string; name?: string; rates?: RawRate[] }[];
};

/* ----------------------------- view model -------------------------------- */

export type BookingSummary = {
  /** use THIS key to book: checkrates can return an updated one */
  rateKey: string;
  hotelName: string;
  roomName: string;
  board: string;
  checkIn: string;
  checkOut: string;
  nights: number;
  guests: string;
  total: string;
  perNight?: string;
  taxes: { label: string; amount: string }[];
  refundable: boolean;
  cancel: string;
  /** true = card is paid online now; false = pay at the hotel */
  payAtWeb: boolean;
  rateComments?: string;
};

/* ------------------------------- fetch ----------------------------------- */

/**
 * ⚠️ ASSUMPTION – adjust URL to your backend.
 * Re-checks a rate right before booking (required for RECHECK rates, safe for all).
 */
export async function fetchCheckRate(rateKey: string): Promise<RawCheckRateHotel | null> {
  const base = process.env.API_BASE_URL ?? "http://localhost:3000";
  const res = await fetch(`${base}/api/v1/hotels/checkrates`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    cache: "no-store",
    body: JSON.stringify({ rooms: [{ rateKey }] }),
  });
  if (!res.ok) return null;

  const json = await res.json();
  const root = json?.data ?? json;
  return root?.hotel ?? root?.hotels?.[0] ?? null;
}

/* ------------------------------- helpers --------------------------------- */

const SMALL_WORDS = new Set(["de", "del", "la", "las", "los", "el", "y", "of", "and", "da", "do"]);

function titleCase(s = ""): string {
  return s
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map((w, i) => (i > 0 && SMALL_WORDS.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(" ");
}

function money(amount: number, currency = "EUR"): string {
  try {
    return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(2)}`;
  }
}

function shortDate(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime())
    ? ""
    : d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
}

function cancellation(r: RawRate): { text: string; refundable: boolean } {
  const policies = [...(r.cancellationPolicies ?? [])].sort(
    (a, b) => new Date(a.from).getTime() - new Date(b.from).getTime()
  );
  const first = policies[0] ? new Date(policies[0].from) : null;
  if (!first || Number.isNaN(first.getTime())) {
    return { text: "Check the cancellation policy", refundable: false };
  }
  return first.getTime() > Date.now()
    ? { text: `Free cancellation until ${shortDate(policies[0].from)}`, refundable: true }
    : { text: "Non-refundable", refundable: false };
}

/* ------------------------------- mapper ---------------------------------- */

export function toBookingSummary(
  h: RawCheckRateHotel,
  ctx: { checkIn: string; checkOut: string; adults: number; children: number; rooms: number }
): BookingSummary | null {
  const room = h.rooms?.[0];
  const rate = room?.rates?.[0];
  if (!room || !rate) return null;

  const amount = Number(rate.sellingRate ?? rate.net);
  if (!Number.isFinite(amount)) return null;

  const currency = h.currency ?? "EUR";
  const nights = countNights(ctx.checkIn, ctx.checkOut);

  // taxes NOT included in the price are paid at the hotel
  const due = (rate.taxes?.taxes ?? []).filter((t) => t.included === false && (t.clientAmount ?? t.amount));
  const taxes: BookingSummary["taxes"] = [];
  if (due.length) {
    const cur = due[0].clientCurrency ?? due[0].currency ?? currency;
    const sum = due
      .filter((t) => (t.clientCurrency ?? t.currency ?? currency) === cur)
      .reduce((acc, t) => acc + Number(t.clientAmount ?? t.amount ?? 0), 0);
    if (sum > 0) taxes.push({ label: "Taxes & fees", amount: money(sum, cur) });
  }

  const cancel = cancellation(rate);
  const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;

  return {
    rateKey: rate.rateKey,
    hotelName: h.name ? titleCase(h.name) : "Your hotel",
    roomName: titleCase(room.name ?? room.code),
    board: titleCase(rate.boardName ?? rate.boardCode ?? "Room only"),
    checkIn: formatDate(ctx.checkIn),
    checkOut: formatDate(ctx.checkOut),
    nights,
    guests: [
      plural(ctx.adults, "adult"),
      ctx.children ? plural(ctx.children, "child").replace("childs", "children") : null,
      plural(ctx.rooms, "room"),
    ]
      .filter(Boolean)
      .join(", "),
    total: money(amount, currency),
    perNight: nights > 1 ? money(amount / nights, currency) : undefined,
    taxes,
    refundable: cancel.refundable,
    cancel: cancel.text,
    payAtWeb: rate.paymentType !== "AT_HOTEL",
    rateComments: rate.rateComments?.trim() || undefined,
  };
}